<template>
	<view v-if="visible" class="success-fly-modal" @touchmove.stop.prevent>
		<view class="success-fly-bg" />
		<view v-if="!leaving" class="success-fly-trail" />
		<view class="success-fly-stage" @click.stop>
			<view class="success-fly-body" :class="{ 'is-out': leaving }">
				<view class="success-fly-tape" />
				<view class="success-fly-icon">
					<view class="success-fly-ring success-fly-ring-1" />
					<view class="success-fly-ring success-fly-ring-2" />
					<view class="success-fly-circle">
						<view class="success-fly-check" />
					</view>
					<view class="success-fly-particles">
						<view v-for="i in 8" :key="i" class="success-fly-particle" :class="`p-${i}`"></view>
					</view>
				</view>
				<text class="success-fly-label">{{ label }}</text>
				<text v-if="sublabel" class="success-fly-sublabel">{{ sublabel }}</text>
			</view>
		</view>
	</view>
</template>

<script>
export default {
	name: 'SuccessFlyModal',
	props: {
		visible: { type: Boolean, default: false },
		label: { type: String, default: '放飞成功' },
		sublabel: { type: String, default: '' }
	},
	data() {
		return {
			leaving: false,
			_inTimer: null,
			_outTimer: null
		};
	},
	watch: {
		visible(next) {
			this.clearTimers();
			if (next) {
				this.leaving = false;
				this._outTimer = setTimeout(() => {
					this.leaving = true;
					this._outTimer = setTimeout(() => {
						this.leaving = false;
						this.$emit('close');
					}, 520);
				}, 1700);
			}
		}
	},
	beforeUnmount() {
		this.clearTimers();
	},
	methods: {
		clearTimers() {
			if (this._inTimer) {
				clearTimeout(this._inTimer);
				this._inTimer = null;
			}
			if (this._outTimer) {
				clearTimeout(this._outTimer);
				this._outTimer = null;
			}
		}
	}
};
</script>

<style lang="scss" scoped>
.success-fly-modal {
	position: fixed;
	inset: 0;
	z-index: 9999;
	display: flex;
	align-items: center;
	justify-content: center;
}

.success-fly-bg {
	position: absolute;
	inset: 0;
	background: rgba(255, 250, 253, 0.5);
	backdrop-filter: blur(14rpx) saturate(170%);
	-webkit-backdrop-filter: blur(14rpx) saturate(170%);
	animation: success-fly-bg-in 320ms ease-out both;
}

@keyframes success-fly-bg-in {
	from { opacity: 0; }
	to { opacity: 1; }
}

.success-fly-trail {
	position: absolute;
	left: 8%;
	top: 14%;
	width: 60%;
	height: 22%;
	background: linear-gradient(120deg, rgba(212, 104, 138, 0.32) 0%, rgba(255, 200, 220, 0) 70%);
	filter: blur(8rpx);
	transform: rotate(-22deg);
	transform-origin: left top;
	animation: success-fly-trail-in 720ms cubic-bezier(0.18, 0.85, 0.32, 1.18) both;
	pointer-events: none;
}

@keyframes success-fly-trail-in {
	0% { opacity: 0; transform: rotate(-22deg) scale(0.4); }
	60% { opacity: 0.85; }
	100% { opacity: 0; transform: rotate(-22deg) scale(1); }
}

.success-fly-stage {
	position: relative;
	z-index: 2;
	display: flex;
	align-items: center;
	justify-content: center;
}

.success-fly-body {
	position: relative;
	display: flex;
	flex-direction: column;
	align-items: center;
	padding: 88rpx 86rpx 56rpx;
	box-sizing: border-box;
	border-radius: 36rpx;
	background:
		linear-gradient(180deg, rgba(255, 245, 250, 0.98), rgba(255, 255, 255, 1));
	border: 1rpx solid rgba(238, 220, 235, 0.92);
	box-shadow:
		0 36rpx 88rpx rgba(45, 28, 60, 0.22),
		inset 0 1rpx 0 rgba(255, 255, 255, 1);
	min-width: 360rpx;
	transform-origin: center center;
	animation: success-fly-body-in 720ms cubic-bezier(0.18, 0.85, 0.32, 1.18) both;
}

.success-fly-body.is-out {
	animation: success-fly-body-out 520ms cubic-bezier(0.4, 0, 0.6, 1) forwards;
}

@keyframes success-fly-body-in {
	0% {
		opacity: 0;
		transform: translate(-680rpx, -560rpx) rotate(-22deg) scale(0.42);
	}
	60% {
		opacity: 1;
		transform: translate(22rpx, 18rpx) rotate(2deg) scale(1.08);
	}
	80% {
		transform: translate(-8rpx, -6rpx) rotate(-1deg) scale(0.992);
	}
	100% {
		opacity: 1;
		transform: translate(0, 0) rotate(0) scale(1);
	}
}

@keyframes success-fly-body-out {
	0% {
		opacity: 1;
		transform: translate(0, 0) rotate(0) scale(1);
	}
	100% {
		opacity: 0;
		transform: translate(-300rpx, 720rpx) rotate(18deg) scale(0.55);
	}
}

.success-fly-tape {
	position: absolute;
	top: -22rpx;
	width: 138rpx;
	height: 36rpx;
	border-radius: 10rpx;
	background: rgba(255, 221, 234, 0.78);
	box-shadow: 0 10rpx 22rpx rgba(212, 104, 138, 0.16);
	transform: rotate(-6deg);
	animation: success-fly-tape-in 460ms 720ms ease-out both;
}

@keyframes success-fly-tape-in {
	0% { opacity: 0; transform: translateY(-30rpx) rotate(-22deg); }
	100% { opacity: 1; transform: translateY(0) rotate(-6deg); }
}

.success-fly-icon {
	position: relative;
	width: 200rpx;
	height: 200rpx;
	display: flex;
	align-items: center;
	justify-content: center;
}

.success-fly-ring {
	position: absolute;
	width: 160rpx;
	height: 160rpx;
	border-radius: 50%;
	border: 4rpx solid rgba(212, 104, 138, 0.5);
	opacity: 0;
	transform: scale(0.5);
}

.success-fly-ring-1 {
	animation: success-fly-ring-out 760ms 360ms cubic-bezier(0.2, 0.72, 0.3, 1) both;
}

.success-fly-ring-2 {
	animation: success-fly-ring-out 920ms 480ms cubic-bezier(0.2, 0.72, 0.3, 1) both;
}

@keyframes success-fly-ring-out {
	0% { opacity: 0; transform: scale(0.5); }
	40% { opacity: 0.7; transform: scale(1); }
	100% { opacity: 0; transform: scale(1.6); }
}

.success-fly-circle {
	position: relative;
	width: 144rpx;
	height: 144rpx;
	border-radius: 50%;
	background: linear-gradient(135deg, #ff8ba7, #d4688a);
	box-shadow: 0 24rpx 60rpx rgba(212, 104, 138, 0.36);
	display: flex;
	align-items: center;
	justify-content: center;
	animation: success-fly-circle-in 540ms 240ms cubic-bezier(0.18, 1.4, 0.32, 1) both;
}

@keyframes success-fly-circle-in {
	0% { transform: scale(0); }
	55% { transform: scale(1.14); }
	100% { transform: scale(1); }
}

.success-fly-check {
	width: 56rpx;
	height: 28rpx;
	border-left: 10rpx solid #ffffff;
	border-bottom: 10rpx solid #ffffff;
	transform: translateY(-6rpx) rotate(-45deg) scale(0);
	animation: success-fly-check-in 380ms 580ms cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

@keyframes success-fly-check-in {
	to { transform: translateY(-6rpx) rotate(-45deg) scale(1); }
}

.success-fly-particles {
	position: absolute;
	inset: 0;
	pointer-events: none;
}

.success-fly-particle {
	position: absolute;
	left: 50%;
	top: 50%;
	width: 14rpx;
	height: 14rpx;
	border-radius: 50%;
	background: #d4688a;
	opacity: 0;
	animation: success-fly-particle-out 680ms 720ms ease-out both;
}

.p-1 { --particle-x: -110rpx; --particle-y: -60rpx; background: #ff8ba7; }
.p-2 { --particle-x: -64rpx; --particle-y: -110rpx; background: #efad68; }
.p-3 { --particle-x: 0rpx; --particle-y: -128rpx; background: #7dc9b5; }
.p-4 { --particle-x: 64rpx; --particle-y: -110rpx; background: #efad68; }
.p-5 { --particle-x: 110rpx; --particle-y: -60rpx; background: #ff8ba7; }
.p-6 { --particle-x: 110rpx; --particle-y: 50rpx; background: #b69cf2; }
.p-7 { --particle-x: -110rpx; --particle-y: 50rpx; background: #b69cf2; }
.p-8 { --particle-x: -64rpx; --particle-y: 110rpx; background: #ff8ba7; }

@keyframes success-fly-particle-out {
	0% { opacity: 0; transform: translate(-50%, -50%) scale(0); }
	35% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
	100% { opacity: 0; transform: translate(calc(-50% + var(--particle-x)), calc(-50% + var(--particle-y))) scale(0.55); }
}

.success-fly-label {
	margin-top: 36rpx;
	color: #352238;
	font-size: 34rpx;
	font-weight: 800;
	letter-spacing: 2rpx;
	text-align: center;
	opacity: 0;
	animation: success-fly-text-in 380ms 660ms ease-out forwards;
}

.success-fly-sublabel {
	display: block;
	margin-top: 10rpx;
	color: #a98298;
	font-size: 23rpx;
	line-height: 1.5;
	letter-spacing: 1rpx;
	text-align: center;
	opacity: 0;
	animation: success-fly-text-in 380ms 780ms ease-out forwards;
}

@keyframes success-fly-text-in {
	from { opacity: 0; transform: translateY(8rpx); }
	to { opacity: 1; transform: translateY(0); }
}
</style>
